// crackbot/principles.md
PRINCIPLES = [
  "ethics_before_exploitation",
  "authorization_before_testing",
  "quality_over_quantity",
  "evidence_over_assumptions",
  "team_success_over_individual_recognition",
  "continuous_learning",
  "open_collaboration",
  "responsible_disclosure"
]

function validateFinding(finding) {
  return [
    finding.hasDetectionGuidance,
    finding.hasMitigationSteps,
    finding.hasReproducibleArtifacts,
    finding.hasVendorCoordinationProof,
    finding.peerReviewed
  ].every(Boolean)
}

class Researcher {
  constructor(handle) {
    this.handle = handle;
    this.credibility = 0;
    this.findings = [];
  }

  publish(finding) {
    if (validateFinding(finding)) {
      this.credibility += finding.impactScore;
      this.findings.push(finding);
      return true;
    }
    throw new Error("Finding fails validation gates");
  }
}

// "Curiosity drives research. Integrity builds trust. Collaboration creates impact."
